const fs = require('fs');
const input = (fs.readFileSync(0, 'utf8').match(/\S+/g)) || [];
let idx = 0;

const N = +input[idx++];
const Q = +input[idx++];

const A = new Int32Array(N + 1);
const tree = new Int32Array(N + 1);

// Build Fenwick tree em O(N)
for (let i = 1; i <= N; i++) {
  A[i] = +input[idx++];
  tree[i] += A[i];
  const j = i + (i & -i);
  if (j <= N) tree[j] += tree[i];
}

function update(i, delta) {
  for (; i <= N; i += i & -i) tree[i] += delta;
}

function queryPrefix(i) {
  let s = 0;
  for (; i > 0; i -= i & -i) s += tree[i];
  return s;
}

const out = [];
for (let q = 0; q < Q; q++) {
  const t = input[idx++];
  if (t === '0') {
    const k = +input[idx++];
    const p = +input[idx++];
    update(k, p - A[k]);
    A[k] = p;
  } else {
    const k = +input[idx++];
    out.push(queryPrefix(k));
  }
}

if (out.length) process.stdout.write(out.join('\n') + '\n');
